            and record.get("runner") == runner
            and record.get("condition") == cond
        ):
            return False
        if cond != "no_brain" and delivery_scope and record.get("delivery_scope") != delivery_scope:
            return False
        if require_success:
            return record.get("ok") is True and record.get("valid") is True
